import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Team Space einrichten","description":"Space als Team Space kennzeichnen, Keys vergeben und das Branding der App festlegen.","frontmatter":{"title":"Team Space einrichten","description":"Space als Team Space kennzeichnen, Keys vergeben und das Branding der App festlegen."},"headers":[],"relativePath":"apptiveteams/team-space.md","filePath":"apptiveteams/team-space.md","lastUpdated":1786357627000}'),r={name:"apptiveteams/team-space.md"};function d(s,e,o,c,l,h){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="team-space-einrichten" tabindex="-1">Team Space einrichten <a class="header-anchor" href="#team-space-einrichten" aria-label="Permalink to &quot;Team Space einrichten&quot;">​</a></h1><p>Ein <strong>Team Space</strong> ist ein ganz normaler ApptiveGrid-Space — mit zwei Besonderheiten: Er trägt die Kategorie <code>apptiveTeams</code>, und seine Konfigurations-Grids sind über <strong>Keys</strong> auffindbar.</p><h2 id="space-als-team-space-kennzeichnen" tabindex="-1">Space als Team Space kennzeichnen <a class="header-anchor" href="#space-als-team-space-kennzeichnen" aria-label="Permalink to &quot;Space als Team Space kennzeichnen&quot;">​</a></h2><p>Setzen Sie in den Space-Einstellungen die <strong>Kategorie</strong> auf <code>apptiveTeams</code>.</p><div class="warning custom-block"><p class="custom-block-title">Ohne diese Kategorie erscheint der Space nicht in der App</p><p>Die App bietet ausschließlich Spaces mit der Kategorie <code>apptiveTeams</code> zur Auswahl an. Sieht eine Person „kein Team&quot;, ist das die erste Sache, die Sie prüfen — die zweite ist, ob sie überhaupt Mitglied des Space ist.</p></div><p>→ <a href="/spaces/symbol-und-farbe">Symbol, Farbe und Kategorie</a></p><h2 id="keys-wie-die-app-ihre-grids-findet" tabindex="-1">Keys: wie die App ihre Grids findet <a class="header-anchor" href="#keys-wie-die-app-ihre-grids-findet" aria-label="Permalink to &quot;Keys: wie die App ihre Grids findet&quot;">​</a></h2><p>Ein <strong>Key</strong> ist ein lesbarer Bezeichner, den Grids und Felder zusätzlich zu ihrem Namen tragen können. Die Oberfläche erklärt ihn so:</p><blockquote><p><em>Ein Key ist ein lesbarer Identifier für dieses Grid. Er kann verwendet werden um ein Grid mit einer App zuverbinden.</em></p></blockquote><p>Genau das nutzt ApptiveTeams. Die App sucht nicht nach Grids namens „Konfiguration&quot; oder „Tabs&quot;, sondern nach Grids mit den Keys <code>config</code>, <code>tabs</code> und <code>settings</code>. Namen dürfen Sie also frei wählen und jederzeit ändern.</p><table tabindex="0"><thead><tr><th>Was</th><th>Wo Sie den Key setzen</th></tr></thead><tbody><tr><td><strong>Grid</strong></td><td>Menü (⋮) des Grids → <strong>Grid Key verwalten</strong></td></tr><tr><td><strong>Felder</strong></td><td>Menü (⋮) der Ansicht → <strong>Felder Keys verwalten</strong></td></tr><tr><td>Einzelnes Feld</td><td>Spaltenmenü → <strong>Key der Spalte ändern</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Keys sind exakt zu schreiben</p><p>Groß- und Kleinschreibung zählen. <code>primarycolor</code> ist nicht <code>primaryColor</code>, und ein versehentliches Leerzeichen macht den Key unbrauchbar. Fehlerhafte Keys äußern sich nicht als Fehlermeldung, sondern dadurch, dass Inhalte in der App schlicht fehlen.</p></div><h2 id="die-drei-konfigurations-grids" tabindex="-1">Die drei Konfigurations-Grids <a class="header-anchor" href="#die-drei-konfigurations-grids" aria-label="Permalink to &quot;Die drei Konfigurations-Grids&quot;">​</a></h2><p>Im Team Space erwartet die App drei Grids:</p><table tabindex="0"><thead><tr><th>Grid-Key</th><th>Zweck</th></tr></thead><tbody><tr><td><code>config</code></td><td>Branding der App: Logo, Primärfarbe, Version</td></tr><tr><td><code>tabs</code></td><td>Die Tabs der unteren Navigationsleiste</td></tr><tr><td><code>settings</code></td><td>Zusätzliche Einträge im Einstellungs-Bildschirm</td></tr></tbody></table><p>Dazu kommen die <strong>Inhalts-Grids</strong>, die von den Tabs aus verknüpft werden — je ein Grid pro Kachel- oder Karten-Tab. Diese brauchen keinen Grid-Key, da sie über eine Verknüpfung gefunden werden. → <a href="/apptiveteams/tabs">Tabs einrichten</a></p><div class="tip custom-block"><p class="custom-block-title">Ansichten funktionieren auch</p><p>Als Konfigurations-Grid können Sie sowohl ein normales Grid als auch eine <strong>Ansicht</strong> verwenden. Findet die App beides mit demselben Key, gewinnt die Ansicht.</p><p>Das ist nützlich: Über eine gefilterte Ansicht blenden Sie Inhalte aus, ohne sie zu löschen — etwa Neuigkeiten mit einem Häkchen <code>Veröffentlicht</code>.</p></div><h2 id="branding-festlegen-das-grid-config" tabindex="-1">Branding festlegen: das Grid <code>config</code> <a class="header-anchor" href="#branding-festlegen-das-grid-config" aria-label="Permalink to &quot;Branding festlegen: das Grid `config`&quot;">​</a></h2><p>Das Grid mit dem Key <code>config</code> steuert das Erscheinungsbild der App. Ausgewertet wird nur die <strong>erste Zeile</strong>.</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>logo</code></td><td>Anhang (Bild)</td><td>ja</td><td>Logo Ihres Unternehmens, erscheint z. B. über der Kachel-Ansicht</td></tr><tr><td><code>primaryColor</code></td><td>Text</td><td>ja</td><td>Primärfarbe als Hex-Wert, etwa <code>#1565C0</code>. Färbt Icons, Buttons und die aktive Tab-Markierung</td></tr><tr><td><code>version</code></td><td>Text / Zahl</td><td>nein</td><td>Version des Team-Space-Schemas. Aktuell <code>1</code>; ohne Angabe wird <code>1</code> angenommen</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Fehlt Logo oder Farbe, greift gar kein Branding</p><p>Die App wertet die Konfigurationszeile nur aus, wenn <strong>beide</strong> Pflichtfelder gefüllt sind. Fehlt eines, wird die ganze Zeile verworfen — die App startet dann ohne Logo <em>und</em> ohne Ihre Farbe, nicht etwa nur ohne das fehlende Stück.</p><p>Die Farbe muss ein Hex-Wert sein. Ein Farbname wie <code>blau</code> funktioniert nicht.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/apptiveteams/einstellungen">Einstellungs-Bildschirm ergänzen</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>',23)])])}const u=t(r,[["render",d]]);export{g as __pageData,u as default};
